import {calculate,compare,breakEvenGrid,project,DEFAULTS,ALTERNATIVE} from './model.mjs';
const main=document.querySelector('main'),nav=document.querySelector('#nav');
const icons={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',lab:'M9 3v6l-5 10a1 1 0 0 0 1 2h14a1 1 0 0 0 1-2L15 9V3 M7 3h10 M7 15h10',india:'M12 3c-4 0-7 3-7 7 0 5 7 11 7 11s7-6 7-11c0-4-3-7-7-7Z M9 10a3 3 0 1 0 6 0 3 3 0 1 0-6 0',futures:'M3 19V5 M3 19h18 M6 15l5-5 4 3 6-8',evidence:'M5 3h11l4 4v14H5z M15 3v5h5 M8 12h9 M8 16h6',solutions:'M12 3v3 M4 6l2 2 M20 6l-2 2 M9 18h6 M10 21h4 M8 14a6 6 0 1 1 8 0c-1 1-1 2-1 4H9c0-2 0-3-1-4'};
const pages=[['overview','Overview'],['lab','Decision lab'],['companies','Company reporting'],['locations','Location context'],['india','India observatory'],['futures','Future scenarios'],['evidence','Evidence & methods'],['solutions','Solutions playbook']];
nav.innerHTML=pages.map(([id,t])=>`<a href="#${id}" data-page="${id}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[id]??icons.evidence}"/></svg>${t}${id==='india'?'<span class="nav-count">36</span>':''}</a>`).join('');
const state={b:{...DEFAULTS},a:{...ALTERNATIVE},growth:10,efficiency:5};
const fmt=(n,d=0)=>new Intl.NumberFormat('en-IN',{maximumFractionDigits:d,minimumFractionDigits:d}).format(n);
const volume=n=>Math.abs(n)>=1e6?`${fmt(n/1e6,2)} ML`:Math.abs(n)>=1000?`${fmt(n/1000,1)} kL`:`${fmt(n)} L`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tag=(text,type='')=>`<span class="tag ${type}">${esc(text)}</span>`;
const download=(name,text,type='text/csv')=>{const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);};
const csv=rows=>rows.map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\r\n');
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),3000);}
let data;
try{const r=await fetch('./data/evidence.json');if(!r.ok)throw new Error(`HTTP ${r.status}`);data=await r.json();}catch(e){main.innerHTML=`<div class="callout warning">Evidence could not be loaded. Serve this folder through HTTP and reload. ${esc(e.message)}</div>`;throw e;}
const source=id=>data.sources.find(s=>s.id===id);
const link=(id,label)=>`<a href="${esc(source(id).url)}" target="_blank" rel="noopener noreferrer">${esc(label??source(id).publisher)} ↗</a>`;
const pagehead=(k,t,p)=>`<div class="pagehead"><div class="eyebrow">${k}</div><h1>${t}</h1><p>${p}</p></div>`;
function art(){return `<div class="hero-art"><span class="art-label">THE WATER–ENERGY CONNECTION</span><svg viewBox="0 0 460 300" role="img" aria-label="Concept diagram: IT servers use electricity, produce heat, and connect to cooling and power-generation water use."><defs><radialGradient id="halo"><stop stop-color="#3c8b8e" stop-opacity=".25"/><stop offset="1" stop-color="#10242d" stop-opacity="0"/></radialGradient><linearGradient id="drop" x2="1" y2="1"><stop stop-color="#b7f3e6"/><stop offset="1" stop-color="#4b979e"/></linearGradient><pattern id="grid" width="22" height="22" patternUnits="userSpaceOnUse"><path d="M22 0H0V22" fill="none" stroke="#294955" stroke-width=".5" opacity=".4"/></pattern></defs><ellipse cx="236" cy="152" rx="210" ry="135" fill="url(#halo)"/><rect x="20" y="10" width="420" height="275" fill="url(#grid)"/><ellipse cx="236" cy="150" rx="142" ry="97" fill="none" stroke="#35545d" stroke-dasharray="3 6"/><ellipse cx="236" cy="150" rx="112" ry="112" fill="none" stroke="#25424b"/><ellipse cx="236" cy="150" rx="92" ry="58" fill="none" stroke="#3c6970"/><path d="M235 56C220 86 180 120 180 154a55 55 0 0 0 110 0c0-34-40-68-55-98Z" fill="url(#drop)" opacity=".95"/><path d="M198 156c0 24 15 40 36 40" fill="none" stroke="#c7fff1" stroke-opacity=".6" stroke-width="3" stroke-linecap="round"/><path d="M180 141H107M291 153h77M234 210v38" stroke="#73a4aa" stroke-dasharray="3 4"/><g fill="#122a34" stroke="#3a626a"><rect x="27" y="103" width="111" height="56" rx="7"/><rect x="330" y="127" width="112" height="56" rx="7"/><rect x="182" y="236" width="108" height="45" rx="7"/></g><g font-family="sans-serif" text-anchor="middle"><text x="83" y="125" fill="#8ce2da" font-size="10">ELECTRICITY</text><text x="83" y="143" fill="#8da8b6" font-size="9">power-generation water</text><text x="385" y="149" fill="#8ce2da" font-size="10">COOLING</text><text x="385" y="168" fill="#8da8b6" font-size="9">on-site consumption</text><text x="236" y="263" fill="#b9d2db" font-size="10">AI & IT WORKLOADS</text></g><g fill="#a2e3db"><circle cx="105" cy="141" r="3"/><circle cx="369" cy="153" r="3"/><circle cx="234" cy="220" r="3"/></g></svg><div class="art-bottom">Conceptual system boundary · not a geographic map</div></div>`;}
function overview(){return `<section class="hero"><div><div class="eyebrow">An open evidence atlas & decision lab</div><h1>AI runs on code.<br>The cloud runs<br>on <em>resources.</em></h1><p class="lede">Water is part of AI's physical footprint. But there is no single number. Explore how cooling, electricity and location change the answer—and which choices can help.</p><div class="buttons"><a class="btn" href="#lab">Explore the decision lab <span>↗</span></a><a class="btn ghost" href="#evidence">Inspect the evidence</a></div></div>${art()}</section><div class="trustbar"><span>Primary sources, traceable claims</span><span>Reported evidence ≠ scenarios</span><span>No universal water-per-prompt figure</span></div><section class="kpis" aria-label="Research context"><article class="card kpi"><div class="label">GLOBAL DATA-CENTRE ELECTRICITY · 2030</div><div class="number">950 <small>TWh / year</small></div><div class="note">${tag('IEA PROJECTION','blue')} <span>All data centres · C02</span></div></article><article class="card kpi"><div class="label">2030 PROJECTION VS 2025 ESTIMATE</div><div class="number">${fmt(950/485,2)}× <small>electricity demand</small></div><div class="note">Derived from 950 / 485 · C01, C02</div></article><article class="card kpi"><div class="label">INDIA GROUNDWATER CONTEXT · 2025</div><div class="number">36 <small>states & UTs</small></div><div class="note">${tag('GOVERNMENT REPORTED')} <span>CGWB / PIB</span></div></article></section><section class="cols"><article class="card"><div class="sectionhead"><div><h2>The scale is changing.</h2><p>Global data-centre electricity demand · TWh/year</p></div>${tag('SOURCE: IEA 2026','blue')}</div><svg class="chart" viewBox="0 0 560 230" role="img" aria-label="IEA estimates global data-centre electricity demand at 485 TWh in 2025 and projects 950 TWh in 2030."><g class="gridline"><path d="M48 185H535M48 105H535M48 25H535"/></g><g fill="#738f9d" font-size="10"><text x="12" y="189">0</text><text x="5" y="109">500</text><text x="0" y="29">1,000</text></g><rect x="123" y="107.4" width="105" height="77.6" fill="#416679" rx="4"/><rect x="335" y="33" width="105" height="152" fill="#8ce2da" rx="4"/><g text-anchor="middle"><text x="175" y="95" fill="#afc7d2" font-size="23">485</text><text x="387" y="23" fill="#b0eee7" font-size="23">950</text><text x="175" y="210" fill="#a1b8c4" font-size="11">2025 estimate</text><text x="387" y="210" fill="#a1b8c4" font-size="11">2030 projection</text></g></svg><p class="source-note">${link('IEA26')} · C01–C02 · Two source endpoints, not an invented annual trajectory. Electricity is not water; AI is one part of data-centre demand.</p><div class="insight">So what? Growth makes cooling and power choices worth examining. This chart does not establish a global AI water total.</div></article><article class="card"><div class="eyebrow">Follow the physical chain</div><h2>Two paths to water use.</h2><div class="mechanism"><div><b>▤</b>IT work</div><span>→</span><div><b>ϟ</b>Electricity</div><span>→</span><div><b>≈</b>Heat</div></div><h3>01 / At the data centre</h3><p class="subtle">Some cooling systems consume water on site, often through evaporation. Heat rejection design matters.</p><hr class="divider"><h3>02 / At the power source</h3><p class="subtle">Producing electricity can also consume water. The amount and location depend on the generation and cooling mix.</p><a class="small-link" href="#evidence">Understand the accounting boundary ↗</a></article></section><section class="feature-row"><article class="card"><div class="index">01 / EXPERIMENT</div><h3>Less direct water. More power?</h3><p>Test when lower on-site water demand also lowers total operational consumption.</p><a href="#lab" class="small-link">Compare the trade-off ↗</a></article><article class="card"><div class="index">02 / INVESTIGATE</div><h3>India, beyond the average.</h3><p>Explore reported state/UT groundwater conditions. Regional context, without unsupported facility claims.</p><a href="#india" class="small-link">Open the India observatory ↗</a></article><article class="card"><div class="index">03 / ACT</div><h3>From concern to better choices.</h3><p>Examine solutions, constraints and what operators and communities should monitor.</p><a href="#solutions" class="small-link">Read the playbook ↗</a></article></section><div class="callout">Coverage today: <strong>${data.sources.length} registered documents · ${data.claims.length} numerical claims · 36 state/UT records.</strong> Company-reported location records: <strong>${data.locations.length}</strong>; independent remeasurements: <strong>0</strong>. <a href="#companies">Compare disclosures</a> · <a href="#locations">Inspect regional context</a>. A global AI water total is not estimated in this release.</div>`;}
function slider(group,key,label,min,max,step,unit){const v=state[group][key];return `<div class="field"><div class="field-top"><label for="${group}-${key}">${label}</label><output id="${group}-${key}-out" for="${group}-${key}">${fmt(v,step<1?2:0)} ${unit}</output></div><input id="${group}-${key}" data-group="${group}" data-key="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${v}"></div>`;}
function scenarioCard(group,title){return `<article class="card scenario-card ${group==='a'?'alt':''}"><div class="sectionhead"><h3>${title}</h3>${tag('ILLUSTRATIVE INPUTS','amber')}</div>${slider(group,'pue','Facility energy / IT energy (PUE)',1,2.5,.01,'×')}${slider(group,'wue','Direct consumption WUE',0,3,.05,'L/kWh IT')}${slider(group,'grid_l_kwh','Electricity water intensity',0,6,.05,'L/kWh facility')}${slider(group,'carbon_kg_kwh','Electricity carbon intensity',0,1.2,.01,'kg CO₂e/kWh')}<p class="source-note">User-controlled assumptions. This bundle is not a measured facility or a validated technology specification.</p></article>`;}
function lab(){return `${pagehead('Decision lab','A better choice depends on the boundary.','Hold IT work constant. Change cooling and electricity assumptions. See the direct water, electricity-related water, energy and carbon trade-offs together.')}<div class="toolbar"><label for="workload">IT workload (MWh)</label><input type="number" id="workload" min="1" max="1000000000" step="1" value="${state.b.it_mwh}" style="flex:0;width:150px;min-width:140px"><button class="btn ghost small" id="reset">Reset example</button><button class="btn ghost small" id="share">Copy scenario link ↗</button></div><div class="callout warning"><strong>ILLUSTRATIVE INPUTS — NOT MEASUREMENTS.</strong> Default values are hypothetical, not empirical averages. WUE here is direct <em>consumption</em> per IT kWh. Manufacturing, water stress and withdrawal are outside this calculation. Controls can create physically infeasible bundles; use validated engineering inputs before making decisions.</div><div class="pair">${scenarioCard('b','Baseline')}${scenarioCard('a','Alternative')}</div><div id="lab-results" aria-live="polite"></div><details><summary>Inspect the formula and boundary</summary><pre>Facility energy (kWh) = IT energy × PUE
Direct consumption (L) = IT energy × consumptive WUE
Indirect consumption (L) = facility energy × grid water factor
Operational consumption (L) = direct + indirect
Carbon (kg CO₂e) = facility energy × assumed grid carbon factor</pre><p>Water volumes can arise in different basins. Adding them is physical accounting, not a claim that their local impacts are equivalent. Lower carbon does not automatically mean lower water. Renewable procurement alone does not establish local grid water intensity.</p></details>`;}
function updateLab(){const r=compare(state.b,state.a),max=Math.max(r.baseline.total_l,r.alternative.total_l,1),delta=r.water_saved_pct;document.querySelector('#lab-results').innerHTML=`<div class="metric-grid"><article class="card"><div class="label">BASELINE CONSUMPTION</div><div class="number">${volume(r.baseline.total_l)}</div><span class="mini muted">${fmt(r.baseline.facility_mwh)} MWh facility energy</span></article><article class="card"><div class="label">ALTERNATIVE CONSUMPTION</div><div class="number">${volume(r.alternative.total_l)}</div><span class="mini muted">${fmt(r.alternative.facility_mwh)} MWh facility energy</span></article><article class="card"><div class="label">WATER REDUCTION VS BASELINE</div><div class="number ${r.water_saved_l>=0?'positive':'negative'}">${delta===null?'N/A':fmt(delta,1)+'%'}</div><span class="mini muted">${volume(r.water_saved_l)} less (negative = more)</span></article><article class="card"><div class="label">FACILITY ENERGY CHANGE</div><div class="number ${r.energy_change_mwh<=0?'positive':'negative'}">${r.energy_change_mwh>0?'+':''}${fmt(r.energy_change_mwh)} <small>MWh</small></div><span class="mini muted">Same IT work; overhead changes</span></article></div><article class="card"><div class="sectionhead"><div><h2>Follow both water pathways.</h2><p>Direct and electricity-related operational consumption</p></div><button class="btn ghost small" id="export-scenario">Export result ↓</button></div>${[['Baseline',r.baseline],['Alternative',r.alternative]].map(([name,x])=>`<div class="barrow"><span>${name}</span><div class="stack" role="img" aria-label="${name}: ${volume(x.direct_l)} direct, ${volume(x.indirect_l)} indirect"><div class="direct" style="width:${100*x.direct_l/max}%"></div><div class="indirect" style="width:${100*x.indirect_l/max}%"></div></div><strong>${volume(x.total_l)}</strong></div>`).join('')}<div class="legend"><span><i></i>Direct cooling consumption</span><span><i class="blue"></i>Electricity-related consumption</span></div><div class="table-wrap"><table><thead><tr><th>Metric</th><th class="num">Baseline</th><th class="num">Alternative</th></tr></thead><tbody>${[['Direct water',volume(r.baseline.direct_l),volume(r.alternative.direct_l)],['Indirect water',volume(r.baseline.indirect_l),volume(r.alternative.indirect_l)],['Facility energy',fmt(r.baseline.facility_mwh)+' MWh',fmt(r.alternative.facility_mwh)+' MWh'],['Operational carbon',fmt(r.baseline.carbon_kg/1000,2)+' t CO₂e',fmt(r.alternative.carbon_kg/1000,2)+' t CO₂e']].map(row=>`<tr><td>${row[0]}</td><td class="num">${row[1]}</td><td class="num">${row[2]}</td></tr>`).join('')}</tbody></table></div><div class="insight">${r.water_saved_l>=0?'The alternative reduces modeled water consumption under these inputs.':'The alternative increases modeled water consumption under these inputs.'} ${r.energy_change_mwh>0?'It also needs more facility electricity.':'Check electricity and carbon alongside water.'} This is a conditional comparison, not real-world savings achieved.</div><p class="source-note">${breakEvenExplanation()} <br>ML = million liters. kL = thousand liters. All outputs inherit user-selected assumptions.</p></article><article class="card" style="margin-top:20px"><h3>Sensitivity: what if the electricity water factor changes?</h3><p class="subtle">Both cases use the same grid factor below. Other inputs remain as selected.</p><div class="table-wrap"><table><thead><tr><th>Grid factor (L/kWh)</th><th class="num">Baseline water</th><th class="num">Alternative water</th><th class="num">Water reduction</th></tr></thead><tbody>${[0,.5,1,2,4,6].map(g=>{const c=compare({...state.b,grid_l_kwh:g},{...state.a,grid_l_kwh:g});return `<tr><td>${g}</td><td class="num">${volume(c.baseline.total_l)}</td><td class="num">${volume(c.alternative.total_l)}</td><td class="num ${c.water_saved_l>=0?'positive':'negative'}">${c.water_saved_pct===null?'N/A':fmt(c.water_saved_pct,1)+'%'}</td></tr>`}).join('')}</tbody></table></div></article>`;document.querySelector('#export-scenario').onclick=()=>{const obj={warning:'ILLUSTRATIVE INPUTS — NOT MEASUREMENTS',release:'0.2.0',generated_at:new Date().toISOString(),evidence_type:'illustrative_scenario',inputs:{baseline:state.b,alternative:state.a},results:r,limitations:['Not a facility measurement','Manufacturing excluded','No local scarcity impact allocation']};download('thirstyai-scenario.json',JSON.stringify(obj,null,2),'application/json');toast('Result and assumptions exported');};}
function breakEvenExplanation(){if(state.b.grid_l_kwh!==state.a.grid_l_kwh)return 'Break-even grid analysis requires the same grid factor in both cases.';const t=breakEvenGrid(state.b,state.a);if(t===null)return 'Equal PUE: water differences depend on direct WUE under a shared grid.';if(t<0)return 'No non-negative break-even grid factor for these PUE/WUE settings.';return `At a shared grid intensity of ${fmt(t,2)} L/kWh, these cooling inputs have equal total water consumption. The sensitivity table shows which option wins either side.`;}
function bindLab(){document.querySelectorAll('input[data-key]').forEach(input=>input.oninput=()=>{const {group,key}=input.dataset;state[group][key]=Number(input.value);document.querySelector(`#${input.id}-out`).textContent=fmt(Number(input.value),2)+(key==='pue'?' ×':key==='carbon_kg_kwh'?' kg CO₂e/kWh':key==='wue'?' L/kWh IT':' L/kWh facility');updateLab();});document.querySelector('#workload').oninput=e=>{const n=Number(e.target.value);if(!e.target.value||!Number.isFinite(n)||n<1||n>1e9){e.target.setCustomValidity('Enter 1 to 1,000,000,000 MWh');e.target.reportValidity();return;}e.target.setCustomValidity('');state.b.it_mwh=state.a.it_mwh=n;updateLab();};document.querySelector('#reset').onclick=()=>{state.b={...DEFAULTS};state.a={...ALTERNATIVE};history.replaceState(null,'',location.pathname+'#lab');render();toast('Example restored');};document.querySelector('#share').onclick=async()=>{const url=new URL(location.href);url.searchParams.set('scenario',btoa(JSON.stringify({b:state.b,a:state.a})));url.hash='lab';try{await navigator.clipboard.writeText(url.href);toast('Scenario link copied');}catch{download('thirstyai-scenario-link.txt','ILLUSTRATIVE INPUTS - NOT MEASUREMENTS\n'+url.href,'text/plain');toast('Scenario link downloaded');}};updateLab();}
function india(){return `${pagehead('India observatory','One country. Very different water contexts.','Explore the 2025 reported groundwater assessment across 36 states and union territories. These annual, all-use indicators do not measure AI water use or establish local data-centre impact.')}<div class="kpis"><article class="card kpi"><div class="label">NATIONAL STAGE OF EXTRACTION</div><div class="number">60.63<small>%</small></div><div class="note">Reported national value · C03</div></article><article class="card kpi"><div class="label">GEOGRAPHIC COVERAGE</div><div class="number">36 <small>states / UTs</small></div><div class="note">Annexure I · one observation per state/UT</div></article><article class="card kpi"><div class="label">SITE WATER / CAPACITY OBSERVATIONS</div><div class="number">0</div><div class="note">No facility rankings inferred</div></article></div><div class="callout warning"><strong>Read the ratio correctly.</strong> Stage of extraction = annual extraction ÷ annual extractable groundwater resource. A value above 100% means annual extraction exceeds that assessed resource; it is not “more than 100% of groundwater already gone.” State averages can hide local variation.</div><article class="card"><div class="sectionhead"><div><h2>Groundwater, in context.</h2><p>Reported values retained; volumes are rounded by the source.</p></div><a href="data/india_groundwater_2025.csv" download class="btn ghost small">Download data ↓</a></div><div class="toolbar"><input id="india-search" type="search" aria-label="Search state or UT" placeholder="Search a state or union territory…"><select id="india-sort" aria-label="Sort states"><option value="stage">Extraction stage: high → low</option><option value="name">State / UT: A → Z</option><option value="extraction">Annual extraction: high → low</option></select><label class="checkbox"><input id="india-over" type="checkbox"> Above 100% only</label></div><div id="india-result"></div><p class="source-note">${link('CGWB25')} · Annexure I · Assessment year 2025 · BCM = billion cubic meters. Do not recompute published stage values from rounded volume columns; this can materially distort small jurisdictions.</p></article><div class="cols"><article class="card"><h3>For India's data-centre hubs</h3><p class="subtle">Mumbai/Navi Mumbai and Pune sit within Maharashtra; Chennai within Tamil Nadu; Bengaluru within Karnataka; Hyderabad within Telangana. Delhi NCR spans multiple jurisdictions including Delhi, Haryana and Uttar Pradesh.</p><div class="insight">Next evidence needed: exact facility water source, assessment unit or basin, cooling configuration, operating load and monthly demand. A state ratio cannot answer those questions.</div></article><article class="card"><h3>Ask before making a siting claim</h3><div class="steps"><p>Where does the facility actually source water?</p><p>What happens in the dry season?</p><p>Which local users share that source?</p></div></article></div>`;}
function updateIndia(){const q=document.querySelector('#india-search').value.toLowerCase(),sort=document.querySelector('#india-sort').value,over=document.querySelector('#india-over').checked;let rows=data.india.filter(r=>r.state.toLowerCase().includes(q)&&(!over||r.stage_pct>100));rows.sort((a,b)=>sort==='name'?a.state.localeCompare(b.state):sort==='extraction'?b.extraction_bcm-a.extraction_bcm:b.stage_pct-a.stage_pct);document.querySelector('#india-result').innerHTML=`<p class="countline">Showing ${rows.length} of 36 state/UT observations · government reported · 2025</p><div class="table-wrap"><table><thead><tr><th>State / Union territory</th><th class="num">Recharge<br>BCM/year</th><th class="num">Extractable<br>BCM/year</th><th class="num">Extraction<br>BCM/year</th><th class="num">Stage of extraction</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.state)}</td><td class="num">${fmt(r.recharge_bcm,2)}</td><td class="num">${fmt(r.extractable_bcm,2)}</td><td class="num">${fmt(r.extraction_bcm,2)}</td><td class="num"><span class="stage"><span class="stage-track"><i class="${r.stage_pct>100?'over':''}" style="width:${Math.min(r.stage_pct/160*100,100)}%"></i></span>${fmt(r.stage_pct,2)}%</span></td></tr>`).join('')||'<tr><td colspan="5">No states match these filters. Clear the search or change the threshold filter.</td></tr>'}</tbody></table></div>`;}
function futures(){return `${pagehead('Future scenarios','The future is a set of choices.','Explore what demand growth and energy efficiency could mean for the same hypothetical workload. These are project scenarios, not IEA forecasts or probability bands.')}<div class="callout warning"><strong>Illustrative starting point:</strong> the baseline from the decision lab (${fmt(state.b.it_mwh)} MWh IT energy in a hypothetical 2025 baseline). Cooling and grid factors are held constant. Efficiency reduces energy per unit of useful work; demand increases the amount of work.</div><article class="card"><div class="future-inputs"><div class="field"><div class="field-top"><label for="growth">Annual useful-work demand growth</label><output id="growth-out">${state.growth}%</output></div><input id="growth" type="range" min="0" max="35" step="1" value="${state.growth}"></div><div class="field"><div class="field-top"><label for="efficiency">Annual energy-per-work efficiency gain</label><output id="efficiency-out">${state.efficiency}%</output></div><input id="efficiency" type="range" min="0" max="25" step="1" value="${state.efficiency}"></div></div><div id="future-result" aria-live="polite"></div></article><div class="cols"><article class="card"><h3>What the scenario includes</h3><p class="subtle">Energy multiplier = [(1 + demand growth) × (1 − efficiency gain)] ^ years. The water model then uses the selected PUE, consumptive WUE and electricity factors.</p><p class="subtle">Demand and efficiency are chosen independently for exploration; they are not calibrated distributions. Differences between trajectories are not confidence intervals.</p></article><article class="card"><h3>What could change the outcome?</h3><p class="subtle">Task mix, model size, cooling adoption, climate, grid changes, construction delays and rebound effects. This simple model does not claim to predict those processes.</p><a class="small-link" href="#solutions">Explore choices and monitoring ↗</a></article></div>`;}
function futureRows(){return Array.from({length:11},(_,i)=>{const year=2025+i;return{year,chosen:project(state.b,state.growth/100,state.efficiency/100,year),demand:project(state.b,state.growth/100,0,year),slower:project(state.b,state.growth/200,state.efficiency/100,year)};});}
function updateFutures(){const rows=futureRows(),max=Math.max(...rows.flatMap(r=>[r.chosen.total_l,r.demand.total_l,r.slower.total_l]),1),x=i=>55+i*65,y=v=>260-v/max*210,path=key=>rows.map((r,i)=>`${i?'L':'M'}${x(i)},${y(r[key].total_l)}`).join(' ');const end=rows.at(-1);document.querySelector('#future-result').innerHTML=`<div class="sectionhead" style="margin-top:25px"><div><h2>Conditional water trajectories to 2035</h2><p>Operational consumption · million liters per year</p></div><button class="btn ghost small" id="export-future">Export scenarios ↓</button></div><svg class="chart" viewBox="0 0 760 320" role="img" aria-label="Conditional scenario chart. In 2035, selected trajectory is ${volume(end.chosen.total_l)}, demand only ${volume(end.demand.total_l)}, half demand growth ${volume(end.slower.total_l)}.">${[0,.5,1].map(f=>`<path class="gridline" d="M55 ${y(max*f)}H705"/><text fill="#7f99a8" font-size="10" x="7" y="${y(max*f)+4}">${fmt(max*f/1e6,1)}</text>`).join('')}<path class="line-amber" d="${path('demand')}"/><path class="line-blue" d="${path('slower')}"/><path class="line-mint" d="${path('chosen')}"/>${[0,5,10].map(i=>`<text fill="#8ea8b6" font-size="11" text-anchor="middle" x="${x(i)}" y="289">${2025+i}</text>`).join('')}</svg><div class="legend"><span><i></i>Selected growth + efficiency</span><span><i style="background:var(--amber)"></i>Demand growth only</span><span><i class="blue"></i>Half demand growth + efficiency</span></div><div class="metric-grid"><article class="card"><div class="label">YOUR SCENARIO · 2030</div><div class="number">${volume(rows[5].chosen.total_l)}</div></article><article class="card"><div class="label">YOUR SCENARIO · 2035</div><div class="number">${volume(end.chosen.total_l)}</div></article><article class="card"><div class="label">DEMAND ONLY · 2035</div><div class="number">${volume(end.demand.total_l)}</div></article><article class="card"><div class="label">HALF DEMAND GROWTH · 2035</div><div class="number">${volume(end.slower.total_l)}</div></article></div><div class="table-wrap"><table><thead><tr><th>Year</th><th class="num">Selected trajectory</th><th class="num">Demand only</th><th class="num">Half demand growth</th></tr></thead><tbody>${[rows[0],rows[5],rows[10]].map(r=>`<tr><td>${r.year}</td><td class="num">${volume(r.chosen.total_l)}</td><td class="num">${volume(r.demand.total_l)}</td><td class="num">${volume(r.slower.total_l)}</td></tr>`).join('')}</tbody></table></div><p class="source-note">These trajectories are calculated from your assumptions. They are not global AI water estimates. “Half demand growth” means half the selected annual growth rate, with the same efficiency gain.</p>`;document.querySelector('#export-future').onclick=()=>download('thirstyai-conditional-futures.csv',csv([['ILLUSTRATIVE INPUTS - NOT MEASUREMENTS','year','trajectory','water_l','it_mwh','facility_mwh','demand_growth','efficiency_gain','evidence_type'],...rows.flatMap(r=>['chosen','demand','slower'].map(k=>['ILLUSTRATIVE INPUTS - NOT MEASUREMENTS',r.year,k,r[k].total_l,r[k].it_mwh,r[k].facility_mwh,k==='slower'?state.growth/200:state.growth/100,k==='demand'?0:state.efficiency/100,'illustrative_scenario']))]));}

function companies(){return `${pagehead('Company reporting','Same word. Different water accounts.','Three operators publish real observations. The reporting years, fleet boundaries, units and WUE definitions differ. This compares disclosure, not performance.')}<div class="callout warning"><strong>Company self-reported; not independently remeasured by ThirstyAI.</strong> Selected metrics have limited external assurance. Null means a numeric value was not extracted; it never means zero. These values are not automatically compatible with the consumptive decision lab.</div><div class="toolbar"><a href="data/company_water_reports.csv" download class="btn ghost small">Download disclosures ↓</a><a href="#locations" class="btn ghost small">Inspect location context ↗</a></div><div class="table-wrap" tabindex="0" role="region" aria-label="Company reporting comparison"><table><thead><tr><th>Company / metric</th><th>Value and unit</th><th>Period / scope</th><th>Definition / confidence</th><th>Source / locator / caveat</th></tr></thead><tbody>${data.companies.map(c=>`<tr><td>${esc(c.company)}<br>${esc(c.metric)}</td><td>${c.value===null?'Not extracted':fmt(c.value,Number.isInteger(c.value)?0:2)}<br>${esc(c.unit)}</td><td>${esc(c.period)}<br>${esc(c.geography)}<br>${esc(c.scope)}</td><td>${esc(c.water_metric)}<br>${esc(c.energy_denominator)}<br>Extraction: ${esc(c.confidence)}</td><td>${link(c.source_id)}<br>${esc(c.locator)}<br>${esc(c.caveat)}<br><strong>Definitions / periods / fleets differ.</strong></td></tr>`).join('')}</tbody></table></div><h2 style="margin-top:24px">Ask for the missing denominator.</h2><p>Request monthly withdrawal and consumption, source types, exact WUE numerator and denominator, actual supply basin, construction exclusions and assurance scope. Replenishment targets are goals in a separate ledger; they do not erase consumption in the same place and season.</p>`;}
function locations(){return `${pagehead('Location context','A regional warning is not a site diagnosis.','Only officially named locations are included. No facility coordinates, supply basins or missing water values are guessed.')}<div class="metric-grid"><article class="card"><div class="number">${data.locations.length}</div>curated published location records</article><article class="card"><div class="number">${data.overlay.length}</div>US state-context matches</article><article class="card"><div class="number">0</div>verified exact facility/basin joins</article></div><div class="callout warning"><strong>STATE PROXY — NOT FACILITY OR BASIN STRESS.</strong> WRI Aqueduct 4.0's demand-weighted administrative baseline covers 1979–2019. It is not current site conditions, actual utility supply or evidence of causal harm. Unmatched locations are unknown, not low risk.</div><div class="table-wrap" tabindex="0" role="region" aria-label="Locations with regional context"><table><thead><tr><th>Published location</th><th>Reported water / boundary</th><th>State context</th><th>Source trail</th></tr></thead><tbody>${data.overlay.map(r=>`<tr><td>${esc(r.company)}<br>${esc(r.location)}</td><td>${esc(r.value)} ${esc(r.unit)}<br>${esc(r.water_metric)} · ${esc(r.period)}<br>${esc(r.scope)}<br>Extraction: ${esc(r.confidence)}</td><td>${esc(r.stress_region)}<br>${esc(r.stress_label)}<br>Score ${esc(r.stress_score)} (dimensionless)<br>${esc(r.stress_period)}<br>Geographic match: ${esc(r.match_confidence)}</td><td>${link(r.source_id)}: ${esc(r.locator)}<br>${link(r.stress_source_id)}: ${esc(r.stress_locator)}</td></tr>`).join('')}</tbody></table></div><p>WRI Aqueduct extract: CC BY 4.0; accessed 22 October 2026. No scarcity-weighted water footprint is calculated.</p><a href="data/location_stress_overlay.csv" download class="btn ghost">Download context and caveats ↓</a><h2 style="margin-top:26px">How India fits</h2><p>${link('WRIINDIA26','WRI India’s published siting analysis')} connects data centres and regional water stress. We attribute its analysis without recreating or redistributing its commercial location inventory. Our separate CGWB state table covers all users: it does not estimate AI’s share of extraction.</p><a href="#india" class="btn ghost">Inspect all-use groundwater context ↗</a>`;}

function evidence(){return `${pagehead('Evidence & methods','A claim should come with a trail.','Inspect the observation period, scope, source locator and limitation behind every headline. Estimates, company allocations and projections are labeled separately.')}<div class="data-coverage"><span><strong>${data.sources.length}</strong> registered documents (includes licence / assurance)</span><span><strong>${data.claims.length}</strong> numerical claims</span><span><strong>36</strong> groundwater rows</span><span><strong>${data.locations.length}</strong> company-reported location records</span></div><div class="toolbar"><input type="search" id="claim-search" aria-label="Search headline claims" placeholder="Search a claim, publisher or scope…"><a href="data/claims.csv" download class="btn ghost small">Download claims ↓</a><a href="data/evidence.json" download class="btn ghost small">Download evidence JSON ↓</a></div><div class="evidence-cards" id="claims-list"></div><article class="card" style="margin-top:22px"><h2>Source register</h2><div class="table-wrap"><table><thead><tr><th>ID / Publisher</th><th>Source & locator</th><th>Access status</th></tr></thead><tbody>${data.sources.map(s=>`<tr><td>${esc(s.id)}<br><span class="muted">${esc(s.publisher)}</span></td><td>${link(s.id,s.title)}<br><span class="muted">${esc(s.locator)}</span></td><td>Downloaded, hashed<br><span class="muted">Manual locator review</span></td></tr>`).join('')}</tbody></table></div><p class="source-note">The ingestion pipeline saves raw hashes and checks anchors. Those checks detect source drift; they do not replace human review or independent assurance. Raw third-party documents are excluded from source distribution.</p></article><h2 style="margin-top:30px">What you need to know</h2><details open><summary>Withdrawal and consumption are different metrics.</summary><p>Withdrawal is water taken from a source. Consumption is the portion not returned within the accounting boundary, often through evaporation. Recycled circulation is not a new withdrawal every time around. This calculator uses consumption; a withdrawal-based WUE must not be substituted.</p></details><details><summary>A liter is a volume, not a complete impact measure.</summary><p>Timing, source, basin conditions and other users matter. Direct and power-generation water may occur in different locations. This release does not calculate scarcity-weighted impacts or make facility-level causal claims.</p></details><details><summary>How the calculation works</summary><pre>Total operational water = IT kWh × [WUE + PUE × grid water intensity]</pre><p>Only valid when WUE is direct consumptive water per IT kWh and the grid factor excludes the direct cooling component. Manufacturing, construction, networks and end-user devices are outside the model.</p></details><details><summary>Confidence and limitations</summary><p>Source retrieval and correct attribution are checked. There are no independent facility measurements in this release. Official projections are uncertain; company studies use particular allocation methods; state indicators hide local variation. High confidence labels describe extraction and attribution, not independent remeasurement or resolved local uncertainty.</p></details><details><summary>Data licences and attribution</summary><p>Original code is MIT licensed. Third-party documents retain their terms. IEA and the Google article identify CC BY 4.0; The small WRI administrative extract is attributed under CC BY 4.0; state context is not a facility rating. Indian government facts are attributed to PIB/CGWB; no blanket licence is asserted. Raw HTML/PDF documents are excluded.</p></details>`;}
function updateClaims(){const q=document.querySelector('#claim-search').value.toLowerCase(),rows=data.claims.filter(c=>JSON.stringify(c).toLowerCase().includes(q));document.querySelector('#claims-list').innerHTML=rows.map(c=>`<article class="card"><div class="sectionhead">${tag(c.evidence_type,/projection/.test(c.evidence_type)?'blue':'')}<span class="mini muted">${c.id}</span></div><h3>${esc(c.title)}</h3><div class="number">${fmt(c.value,Number.isInteger(c.value)?0:2)} <small>${esc(c.unit)}</small></div><dl><dt>Period</dt><dd>${esc(c.period)}</dd><dt>Geography</dt><dd>${esc(c.geography)}</dd><dt>Scope / water boundary</dt><dd>${esc(c.scope)} · ${esc(c.water_metric)}</dd><dt>Confidence in extraction</dt><dd>${esc(c.confidence)}</dd><dt>Locator</dt><dd>${esc(c.locator)}</dd></dl><div class="callout" style="margin:12px 0 0">${esc(c.caveat)}</div><div class="source-link">${link(c.source_id)}</div></article>`).join('')||'<div class="callout">No claims match. Try another term.</div>';}
function solutions(){const items=[['01 / COOLING','Match heat rejection to the setting.','Evaluate dry, evaporative and hybrid heat rejection against local climate, energy demand and water constraints. Liquid cooling describes heat transport at the chip or rack; it does not by itself identify the final heat rejection system.','Less evaporative consumption can require more power. Test the whole operational boundary before recommending a design.','MS24'],['02 / ELECTRICITY','Follow water beyond the facility.','Ask how the supplying generators are cooled and where they operate. Use a documented grid factor and distinguish annual accounting from the marginal effects of a change.','Clean-energy procurement claims are not a direct measurement of local water use. Lower carbon is not automatically lower water.','WRI23'],['03 / GOVERNANCE','Make disclosure comparable.','Publish withdrawal and consumption separately, water sources, relevant reporting periods, the WUE denominator, operating boundaries and dry-season data where available.','More transparent reporting improves evaluation; it does not itself reduce consumption. Missing reporting is not evidence of misconduct.','MS24'],['04 / LOCAL CONTEXT','Look below the state average.','Before siting or expanding a facility, investigate actual supply, basin or groundwater assessment unit, drought contingencies and competing users.','A regional indicator is useful context, not proof that a specific data centre caused a local shortage.','CGWB25'],['05 / EFFICIENCY','Reduce energy per useful result.','Evaluate smaller suitable models, caching, batching and efficient serving against quality and latency needs. Track total work and total energy, not efficiency alone.','Efficiency gains can coexist with growing total demand. A company-specific text-serving result is not every AI workload.','GOOGLE25'],['06 / MAINTENANCE','Keep the evidence alive.','Refresh source versions, preserve hashes, review changed definitions and track coverage. For operators, monitor water source, WUE definition, PUE, seasonal consumption and drought response.','A portfolio model is not operational telemetry. Replenishment projects should remain a separate, location-aware ledger.','WRI23']];return `${pagehead('Solutions playbook','Turn evidence into better questions.','There is no universal best cooling technology or city. Start with the local constraint, compare feasible alternatives, then monitor what actually changes.')}<div class="solutions">${items.map(([k,t,p,c,s])=>`<article class="card"><div class="kicker">${k}</div><h2>${t}</h2><p style="margin-top:13px">${p}</p><div class="tradeoff"><strong>Trade-off / limitation</strong><br>${c}</div><span class="source-link">Context: ${link(s)}</span></article>`).join('')}</div><article class="card" style="margin-top:22px"><h2>A prevention and monitoring loop</h2><div class="steps"><p><span><strong>Define the boundary.</strong><br>Separate IT work, facility energy, direct water and electricity-related water.</span></p><p><span><strong>Investigate local constraints.</strong><br>Confirm source, seasonality, other users, and feasible cooling/power options.</span></p><p><span><strong>Compare alternatives.</strong><br>Show baseline, uncertainty, trade-offs, costs when known and break-even conditions.</span></p><p><span><strong>Measure and update.</strong><br>Track real outcomes; document discrepancies, source updates and corrections.</span></p></div><p class="source-note">No liters-saved-per-dollar league table is published: comparable intervention cost and lifetime evidence is not available in this release.</p></article><div class="buttons"><a class="btn" href="#lab">Test a conditional comparison ↗</a><a class="btn ghost" href="#evidence">Check the sources</a></div>`;}
try{const raw=new URL(location.href).searchParams.get('scenario');if(raw){if(raw.length>5000)throw new Error('Too long');const s=JSON.parse(atob(raw));calculate(s.b);calculate(s.a);if(s.b.it_mwh!==s.a.it_mwh)throw new Error('Workload mismatch');for(const k of ['b','a']){if(s[k].it_mwh<1||s[k].it_mwh>1e9||s[k].pue>2.5||s[k].wue>3||s[k].grid_l_kwh>6||s[k].carbon_kg_kwh>1.2)throw new Error('Outside UI bounds');state[k]=Object.fromEntries(Object.keys(DEFAULTS).map(key=>[key,s[k][key]]));}}}catch{toast('Invalid scenario link ignored. Using defaults.');state.b={...DEFAULTS};state.a={...ALTERNATIVE};}
function render(){const key=pages.some(([id])=>id===location.hash.slice(1))?location.hash.slice(1):'overview';document.querySelectorAll('nav a').forEach(a=>{const active=a.dataset.page===key;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.querySelector('#crumb').textContent=pages.find(([id])=>id===key)[1];main.innerHTML=({overview,lab,companies,locations,india,futures,evidence,solutions})[key]();if(key==='lab')bindLab();if(key==='india'){['india-search','india-sort','india-over'].forEach(id=>document.getElementById(id).oninput=updateIndia);updateIndia();}if(key==='evidence'){document.querySelector('#claim-search').oninput=updateClaims;updateClaims();}if(key==='futures'){['growth','efficiency'].forEach(id=>document.getElementById(id).oninput=e=>{state[id]=Number(e.target.value);document.getElementById(id+'-out').textContent=e.target.value+'%';updateFutures();});updateFutures();}document.title=`${pages.find(([id])=>id===key)[1]} · ThirstyAI`;}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});render();
